cd /home/research/phase0/results/followup && date '+%H:%M:%S' && python3 - <<'EOF'
import json, glob, time, os
f=lambda t: time.strftime('%H:%M:%S', time.localtime(t))
rows=[]
for p in glob.glob('*.json'):
    if any(x in p for x in ('-mem.json','annotations','memory-validity','engineering-activity','attribution-check')): continue
    try: r=json.load(open(p))
    except Exception as e: print('unreadable',p,e); continue
    if 'phases' not in r: continue
    rows.append((r.get('exit_epoch',0),p[:-5],r))
rows.sort()
for ex,name,r in rows:
    ph={x['name']:x.get('peak_drop_GiB') for x in r['phases']}
    rel=r.get('release') or {}
    offs=rel.get('offsets_GiB') or {}
    print(f"{name:44s} v{r.get('harness_version')} {f(r['phases'][0]['start'])}-{f(ex)} ok={r.get('ok')} at_ready={r.get('at_ready_drop_GiB')} peak={r.get('peak_drop_GiB')} phases={ph} release={ {k:rel[k] for k in rel if k!='offsets_GiB'} } offs={offs}")
EOF

